import{_ as a,o as s,c as e,a3 as t}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"Sanitizers","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Sanitizers | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/features/sanitizers"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/features/sanitizers"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/features/sanitizers"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/features/sanitizers"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/features/sanitizers"}]]},"headers":[],"relativePath":"xclang/features/sanitizers.md","filePath":"en/xclang/features/sanitizers.md","lastUpdated":1791227177000}'),n={name:"xclang/features/sanitizers.md"};function r(o,i,l,h,d,c){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="sanitizers" tabindex="-1">Sanitizers <a class="header-anchor" href="#sanitizers" aria-label="Permalink to &quot;Sanitizers&quot;">​</a></h1><p>compiler-rt carries, for the Linux and macOS targets, AddressSanitizer, ThreadSanitizer, LeakSanitizer, UBSan and libFuzzer, and those targets also carry an ASan build of libc++. Windows targets have no sanitizers yet. MemorySanitizer is not there: it needs every library instrumented.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsanitize=address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsanitize=thread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsanitize=fuzzer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fuzz.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fuzz</span></span></code></pre></div><p>tests/smoke.ts builds and runs each of these on every Linux and macOS host and checks the report.</p><h2 id="asan-and-libc" tabindex="-1">ASan and libc++ <a class="header-anchor" href="#asan-and-libc" aria-label="Permalink to &quot;ASan and libc++&quot;">​</a></h2><p>An ASan program should link libc++&#39;s ASan build, <code>&lt;asan&gt;</code>: <code>lib/asan</code> of the target directory (<code>usr/lib/asan</code> on Linux). It compiles and links with it, all of it, libraries too:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>compile   -fsanitize=address -isystem &lt;asan&gt;/include</span></span>
<span class="line"><span>link      -fsanitize=address -nostdlib++ &lt;asan&gt;/libc++.a</span></span></code></pre></div><p>tests/smoke.ts does both in one command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsanitize=address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -isystem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">asa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nostdlib++</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">asa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/libc++.a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span></span></code></pre></div><p>In Bazel, <code>--features=asan</code> does it; in CMake, add the two to the ASan build&#39;s flags.</p><p><strong>Why.</strong> libc++ annotates its containers for ASan: <code>std::vector</code> tells ASan which part of its buffer is in use, so a read past <code>size()</code> but within <code>capacity()</code> is a <em>container-overflow</em>. The annotations are made by whichever copy of a function runs, and checked on every access. A program compiled with ASan against a libc++ that is not has two kinds of code working on the same container: the program&#39;s instrumented inlines, which annotate, and the library&#39;s uninstrumented copies of the same functions, which do not. When the linker picks one copy of a function for both (a template the library also instantiates, <code>std::vector&lt;std::string_view&gt;</code>&#39;s <code>push_back</code> inside <code>std::filesystem</code>), the annotations no longer match the writes, and ASan reports overflows that are not there. catter&#39;s macOS tests hit exactly this in <code>std::filesystem::relative</code>.</p><p>xclang&#39;s first answer, in 23.1.2.3, was a patch that put ASan into libc++&#39;s ABI tag, so instrumented and uninstrumented copies got different names. Upstream&#39;s answer to the report was that an ASan program with an uninstrumented library is already broken; the patch also could not help with code outside libc++ growing an instrumented container, or with an <code>import std</code> built without ASan. From 23.1.2.5, libc++ itself comes instrumented: its <code>libc++.a</code> built with ASan, and a <code>__config_site</code> that differs from the normal one only in <code>_LIBCPP_INSTRUMENTED_WITH_ASAN</code>, which also turns on <code>std::string</code>&#39;s container checks. Every piece of the program&#39;s C++ is then instrumented the same way, and the reports are real.</p><p>tests/smoke.ts checks both sides: an overflow within a <code>std::string</code>&#39;s capacity is reported, and a program sharing <code>std::filesystem</code>&#39;s instantiations with <code>libc++.a</code> gets no false report.</p><p>The other sanitizers need nothing of the kind: TSan and UBSan programs link the normal libc++.</p><h2 id="on-macos" tabindex="-1">On macOS <a class="header-anchor" href="#on-macos" aria-label="Permalink to &quot;On macOS&quot;">​</a></h2><p>The sanitizers&#39; runtimes are dylibs on macOS (<code>libclang_rt.asan_osx_dynamic.dylib</code> and the rest), which a program loads from the toolchain&#39;s resource directory or from its own directory. An ASan build is for testing, not for shipping, so it is the one exception to <a href="./../design/hermeticity">hermeticity</a>. In Bazel the sanitizer features link the toolchain&#39;s absolute path as an rpath, and only those links depend on the checkout.</p><h2 id="libclang-s-asan-build" tabindex="-1">libclang&#39;s ASan build <a class="header-anchor" href="#libclang-s-asan-build" aria-label="Permalink to &quot;libclang&#39;s ASan build&quot;">​</a></h2><p><code>libclang-&lt;version&gt;-&lt;host&gt;-asan.tar.xz</code>, for Linux x64 and macOS arm64, is clang&#39;s libraries built with assertions and ASan, against libc++&#39;s ASan build, for debugging a tool on libclang (<a href="./libclang">libclang</a>).</p><h2 id="not-there-yet" tabindex="-1">Not there yet <a class="header-anchor" href="#not-there-yet" aria-label="Permalink to &quot;Not there yet&quot;">​</a></h2><ul><li>Sanitizers for Windows targets.</li><li>MemorySanitizer, which needs libc++ instrumented with it too; ThreadSanitizer also reports better through an instrumented libc++. Both need libc++ built from source with the program&#39;s options, which is <a href="./../design/roadmap#libc-built-on-demand">planned</a>.</li></ul>`,20)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
